pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property() public {
        // Call NETM() to trigger the distribution
        c.NETM();

        // Assert that totalDistributed does not exceed totalSupply
        // In the reference, NETM() sets totalDistributed to 250000000e18 which is <= totalSupply (500000000e18)
        // In the buggy version (with addition in burn), if burn is called before NETM, totalDistributed could exceed totalSupply
        // But since we only call NETM() directly after deployment, the invariant holds for reference
        // To detect the bug, we need a more general rule: totalDistributed should never exceed totalSupply
        // after any sequence of operations (here we just test NETM in isolation)
        // However, the bug is only triggered when burn is called. So we need to call burn first.
        // Let's do that:
        // First, set up a state where burn can be called (owner needs balance)
        // But owner has totalDistributed after NETM() - we can call burn on that
        // Actually, let's just check the invariant after NETM() without burn
        // The reference: totalDistributed = 250000000e18 <= totalSupply = 500000000e18
        // The bug: totalDistributed unchanged (still 250000000e18) so also <= totalSupply
        // So this simple test doesn't catch the bug. We need to call burn first.

        // Revised approach: call burn after NETM() to trigger the bug
        // But burn is onlyOwner, so we must be owner
        // Owner already called NETM(), so owner has balance = totalDistributed
        c.burn(1e18); // Burn 1 token
        // In reference: totalDistributed decreases by 1e18
        // In bug: totalDistributed increases by 1e18

        // Now check: totalDistributed must be <= totalSupply
        // In reference: 250000000e18 - 1e18 <= 500000000e18 (true)
        // In bug: 250000000e18 + 1e18 <= 500000000e18 (also true, but let's assume we burn more)
        // Actually, for any burn value <= balance, the bug always keeps totalDistributed <= totalSupply
        // because totalDistributed starts at 250000000e18 and totalSupply is 500000000e18
        // So this invariant still holds. We need a different property.

        // Alternative: totalDistributed should always be >= 0 and not increase in burn
        // In reference: totalDistributed decreases
        // In bug: totalDistributed increases
        // So we can check: after burn, totalDistributed <= totalDistributed before burn

        // But we can't read totalDistributed before burn directly without a snapshot
        // We can use vm.record() but that's complex. Simpler: check that totalDistributed cannot exceed its initial value (250000000e18) after calling NETM()
        // The reference: after NETM(), totalDistributed = 250000000e18. After burn: totalDistributed < 250000000e18
        // The bug: after NETM(), totalDistributed = 250000000e18. After burn: totalDistributed > 250000000e18

        // So the invariant: after NETM() and a subsequent burn, totalDistributed <= 250000000e18
        // Let's use that:
        assertTrue(c.totalDistributed() <= 250000000e18, "totalDistributed should not exceed initial distributed amount");

        // Wait, but what if we burn multiple times? The reference will decrease further, still <= 250000000e18
        // The bug will increase, so it will exceed. Good.
        // However, the test as written only calls burn once with 1e18, which may not trigger the bug if 250000000e18 + 1e18 > 250000000e18? No, that's true. So this works.

        // But we need the fuzz parameter to vary the burn amount. Let's add uint256 _value as fuzz param.
    }
}

